  ('cpiuris2025::59324290c58935634a8ec1ec2b226940', 'doutrina', 'cp_iuris', 'Direitos Internacional — Disponibilidade Permanente e Secretaria do Tribunal Permanente de Revisão', '## Disponibilidade Permanente e Secretaria do Tribunal Permanente de Revisão

