  ('cpiuris2025::361b194129113382cf16d617cf142445', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratado de Assunção e outros instrumentos do MERCOSUL', '## Tratado de Assunção e outros instrumentos do MERCOSUL

