  ('cpiuris2025::a9adccc108c603dae2ede1930e33e14b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cumprimento de medidas cautelares por carta rogatória', '## Cumprimento de medidas cautelares por carta rogatória

